        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ElectionError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = tokens[1]
      if (!COUNT_RE.test(countText)) {
        throw new ElectionError('count must be a positive integer', lineNumber)
      }
      const count = Number(countText)
