{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count described in the task specification and
 * returns the full round-by-round record.
 *
 * The result is `{ rounds, winner }`, where `winner` is a candidate name or
 * `null` when the election ends with no winner, and `rounds` is an array of
 * `{ counts, exhausted, eliminated }`. `counts` lists `{ name, votes }` for
 * every candidate continuing at the start of that round, sorted by
 * descending votes and then ascending name. `eliminated` is the name
 * eliminated after that round, or `null` for the final round.
 */
export function countElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = new Map(candidates.map((name) => [name, []]))
  const rounds = []
  let winner = null

  for (let roundNumber = 1; ; roundNumber++) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const { count, ranking } of ballots) {
      const target = ranking.find((name) => continuing.has(name))
      if (target === undefined) exhausted += count
      else votes.set(target, votes.get(target) + count)
    }

    for (const name of continuing) history.get(name).push(votes.get(name))

    const counts = [...continuing]
      .map((name) => ({ name, votes: votes.get(name) }))
      .sort((a, b) => b.votes - a.votes || (a.name < b.name ? -1 : 1))

    const activeTotal = counts.reduce((sum, c) => sum + c.votes, 0)

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const majority = counts.find((c) => c.votes * 2 > activeTotal)
    if (majority !== undefined) {
      winner = majority.name
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const eliminated = pickElimination(counts, continuing, history, roundNumber)
    rounds.push({ counts, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/** Picks the candidate to eliminate this round, applying the tie-break rule. */
function pickElimination(counts, continuing, history, roundNumber) {
  const fewest = counts[counts.length - 1].votes
  let tied = counts.filter((c) => c.votes === fewest).map((c) => c.name)

  if (tied.length > 1) {
    let narrowed = true
    while (narrowed && tied.length > 1) {
      narrowed = false
      for (let r = 0; r < roundNumber; r++) {
        const values = tied.map((name) => history.get(name)[r])
        const min = Math.min(...values)
        if (values.some((v) => v !== min)) {
          tied = tied.filter((name) => history.get(name)[r] === min)
          narrowed = true
          break
        }
      }
    }
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

