{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection } from './parse.js'
import { countElection } from './count.js'
import { ElectionError } from './errors.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'rounds' && mode !== 'tally') {
  fail('usage: cli.js rounds|tally')
}

const input = readFileSync(0, 'utf8')

let election
try {
  election = parseElection(input)
} catch (err) {
  if (err instanceof ElectionError) {
    fail(err.line === undefined ? err.message : `line ${err.line}: ${err.message}`)
  }
  throw err
}

const { rounds, winner } = countElection(election.candidates, election.ballots)

let output = ''
if (mode === 'rounds') {
  rounds.forEach((round, index) => {
    const counts = round.counts.map((c) => `${c.name}=${c.votes}`).join(' ')
